/**
 * Deterministic generator for 20 synthetic localhost execution traces (Idea 3, Phase 1).
 *
 * Covers:
 * - success (stub and Ollama 1.5B)
 * - approval pause (pending, approved+resumed, rejected)
 * - verification failure + repair (repaired and exhausted)
 * - multi-parent DAG
 * - restart and recovery (lease expiry and checkpoint resume)
 * - tenant isolation (allowed and cross-tenant denied)
 * - tool-output poisoning attempt (untrusted provenance)
 * - secret-shaped string in tool output (redacted)
 * - empty patch (disallowed and false-completion rejected)
 * - timeout (LLM inference and tool execution)
 * - operator cancellation
 */

import {
  TRACE_FORMAT_VERSION,
  RunTrace,
  TraceModelRecord,
  TraceSpan,
  redactTraceString,
  toRedactedTraceSummary,
  validateRunTrace,
} from "../../src/domain/trace.js";

